Creating a liquidity pool contract that can swap any token requires implementing an interface to interact with ERC20 tokens and adhering to the necessary logic for adding liquidity, removing liquidity, and swapping tokens. Below is a simplified Solidity smart contract that demonstrates these basic functionalities.

Please note that this example does not include important considerations such as security checks, proper mathematical operations to prevent integer overflows/underflows, or fees. Before deploying such a contract to the mainnet, ensure to add these checks, use safe math operations, and thoroughly audit and test the contract.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract LiquidityPool {
    address public tokenA;
    address public tokenB;
    uint256 public reserveA;
    uint256 public reserveB;

    mapping(address => uint256) public liquidityProviders;

    constructor(address _tokenA, address _tokenB) {
        require(_tokenA != _tokenB, "Cannot have two identical tokens in a pair");
        tokenA = _tokenA;
        tokenB = _tokenB;
    }

    // Ensure tokens are sent to this contract
    modifier ensure(uint256 deadline) {
        require(deadline >= block.timestamp, 'LiquidityPool: EXPIRED');
        _;
    }

    // Add liquidity to the pool
    function addLiquidity(uint256 amountA, uint256 amountB, uint256 deadline) external ensure(deadline) {
        IERC20(tokenA).transferFrom(msg.sender, address(this), amountA);
        IERC20(tokenB).transferFrom(msg.sender, address(this), amountB);
        reserveA += amountA;
        reserveB += amountB;
        liquidityProviders[msg.sender] += amountA + amountB; // Simplified LP token logic
    }

    // Remove liquidity from the pool
    function removeLiquidity(uint256 liquidity, uint256 deadline) external ensure(deadline) {
        require(liquidityProviders[msg.sender] >= liquidity, "Not enough liquidity provided");
        uint256 amountA = liquidity * reserveA / (reserveA + reserveB);
        uint256 amountB = liquidity * reserveB / (reserveA + reserveB);
        reserveA -= amountA;
        reserveB -= amountB;
        liquidityProviders[msg.sender] -= liquidity;
        IERC20(tokenA).transfer(msg.sender, amountA);
        IERC20(tokenB).transfer(msg.sender, amountB);
    }

    // Swap tokens
    function swap(address fromToken, uint256 amountIn, uint256 deadline) external ensure(deadline) {
        require(fromToken == tokenA || fromToken == tokenB, "Invalid token");
        address toToken = fromToken == tokenA ? tokenB : tokenA;
        uint256 amountOut;

        if (fromToken == tokenA) {
            require(amountIn <= reserveA, "Insufficient reserve");
            amountOut = amountIn * reserveB / (reserveA + amountIn); // Simplified pricing logic
            reserveA += amountIn;
            reserveB -= amountOut;
        } else {
            require(amountIn <= reserveB, "Insufficient reserve");
            amountOut = amountIn * reserveA / (reserveB + amountIn); // Simplified pricing logic
            reserveB += amountIn;
            reserveA -= amountOut;
        }

        IERC20(fromToken).transferFrom(msg.sender, address(this), amountIn);
        IERC20(toToken).transfer(msg.sender, amountOut);
    }

    // Get reserves
    function getReserves() external view returns (uint256 _reserveA, uint256 _reserveB) {
        return (reserveA, reserveB);
    }
}
```

This contract allows users to add liquidity to the pool, remove liquidity, and swap tokens. The `swap` function contains a simplified pricing mechanism and does not account for fees or slippage, which are important for a real-world deployment. Additionally, in a production environment, you'd likely implement an automated market maker (AMM) model such as the Constant Product Formula used by Uniswap.

